import { CalculateMetadataFunction, Composition } from "remotion";
import { Main, MainProps } from "./Main";
import { VIDEO_FPS, VIDEO_HEIGHT, VIDEO_WIDTH } from "./config";
import { END_HOLD_FRAMES, loadTiming } from "./lib/timing";

// Duration and timing come from public/timing.json (generated by generate_audio.py).
const calculateMetadata: CalculateMetadataFunction<MainProps> = async ({ props }) => {
  const timing = await loadTiming();
  if (timing.fps !== VIDEO_FPS) {
    throw new Error(`timing.json was generated at ${timing.fps} fps, composition is ${VIDEO_FPS} fps`);
  }
  return {
    durationInFrames: timing.totalDurationInFrames + END_HOLD_FRAMES,
    props: { ...props, timing },
  };
};

export const RemotionRoot: React.FC = () => {
  return (
    <Composition
      id="Main"
      component={Main}
      width={VIDEO_WIDTH}
      height={VIDEO_HEIGHT}
      fps={VIDEO_FPS}
      durationInFrames={1}
      defaultProps={{ showTikTokOverlay: true, timing: null } satisfies MainProps}
      calculateMetadata={calculateMetadata}
    />
  );
};
